referenceSolutions.javascript:
function cancelingStampsEvenKeyCensus(readings, k) {
  const a=readings; let out=[];
  for(const x of a){if(out.length&&out[out.length-1]===x)out.pop();else out.push(x);}
  return out.filter(x=>x%2===0).length;
}

